<?php
require_once 'config.php';
$count=(int)db()->query("SELECT COUNT(*) FROM users")->fetchColumn();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST' && $count===0){check_csrf();$name=trim($_POST['full_name']);$user=trim($_POST['username']);$pass=$_POST['password'];if(strlen($pass)<8)$msg='Le mot de passe doit contenir au moins 8 caractères.';else{$q=db()->prepare("INSERT INTO users(username,password_hash,full_name,role) VALUES(?,?,?, 'admin')");$q->execute([$user,password_hash($pass,PASSWORD_DEFAULT),$name]);header('Location: login.php');exit;}}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Créer administrateur</title></head><body class="login-bg"><form class="login-card" method="post"><?=csrf_field()?><h1>Créer l'administrateur</h1><?php if($count):?><div class="alert">Un compte existe déjà. Connectez-vous.</div><a href="login.php">Aller à la connexion</a><?php else:?><?php if($msg):?><div class="alert"><?=h($msg)?></div><?php endif?><label>Nom complet</label><input name="full_name" required><label>Nom d'utilisateur</label><input name="username" required><label>Mot de passe (8 caractères minimum)</label><input type="password" name="password" required minlength="8"><button class="btn primary full">Créer le compte</button><?php endif?></form></body></html>
